// Script to generate storybook config file at build time
const fs = require('fs');
const path = require('path');

const isStorybook = process.env.STORYBOOK === '1';
const configFile = path.join(__dirname, '..', 'storybook-config.ts');

const configContent = `// Auto-generated file - DO NOT EDIT
// This file is generated by scripts/generate-storybook-flag.js
// Run 'npm run storybook' to enable Storybook mode

export const IS_STORYBOOK_MODE = ${isStorybook};
`;

fs.writeFileSync(configFile, configContent, 'utf8');
console.log(`✅ Storybook config generated: IS_STORYBOOK_MODE = ${isStorybook}`);

